import{_ as a,a0 as p,w as l,s as i,ao as u,I as s,x as o,a1 as r,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"谷歌 AI 推出新的數組存儲開源庫 | LCTT x X-CMD","titleTemplate":false,"description":"谷歌 AI 推出新的數組存儲開源庫 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"谷歌 AI 推出新的數組存儲開源庫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"谷歌 AI 推出新的數組存儲開源庫 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20221006 Google AI Unveils A New Open Source Library for Array Storage","title":"谷歌 AI 推出新的數組存儲開源庫","tag":"202210","desc":""},"relativePath":"202210/20221006 Google AI Unveils A New Open Source Library for Array Storage.md","filePath":"[post].md"}'),f={name:"202210/20221006 Google AI Unveils A New Open Source Library for Array Storage.md"};function d(T,e,m,g,A,w){const t=p("Link");return l(),i("div",null,[e[15]||(e[15]=u('<h1 id="谷歌-ai-推出新的數組存儲開源庫" tabindex="-1">谷歌 AI 推出新的數組存儲開源庫 <a class="header-anchor" href="#谷歌-ai-推出新的數組存儲開源庫" aria-label="Permalink to “谷歌 AI 推出新的數組存儲開源庫”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/10/google3-1068x559.jpg" alt=""></p><blockquote><p>谷歌 AI 引入了一個用於數組存儲的高性能開源庫 TensorStore。</p></blockquote><p>谷歌開發的開源 C++ 和 Python 框架 TensorStore 旨在加速大型多維數組的讀寫設計。覆蓋單一大型座標系的多維數據集通常用於當代計算機科學和機器學習應用程序中。使用這些數據集具有挑戰性，因為客户經常希望進行涉及多個工作站並行操作的調查，並且可能會以不可預測的間隔和不同的規模接收和輸出數據。</p><p>谷歌研究院開發了 TensorStore，該庫為用户提供了一個可以管理巨大數據集的 API，而無需複雜的硬件，以解決數據存儲和操作問題。該庫支持許多存儲系統，包括本地和網絡文件系統、谷歌雲存儲等。</p><p>為了加載和處理大量數據，TensorStore 提供了一個簡單的 Python API。任何任意大小的基礎數據集都可以加載和更新，而無需將數據集完整存儲在內存中，因為在需要精確切片之前不需要在內存中讀取或保存實際數據。</p><p>這是通過索引和操作語法實現的，它與 NumPy 操作的語法非常相似。除了虛擬視圖、廣播、對齊和其他複雜的索引功能，TensorStore 還支持如數據類型轉換、降低取樣和隨意創建的數組這些功能。</p><p>此外，TensorStore 包含一個異步 API，可以併發進行讀取或寫入操作。在執行其他工作時，軟件可以進行內存緩存處理（可配置），從而減少在訪問常用數據時處理較慢存儲系統的需要。</p><p>大型數值數據集需要大量的處理能力來檢查和分析。實現這一點的常用方法是在分散在許多設備上的大量 CPU 或加速器內核之間並行化任務。在保持出色速度的同時並行分析單個數據集的能力一直是 TensorStore 的關鍵目標。 PaLM、腦圖和其他複雜的大規模機器學習模型是 TensorStore 應用案例的一些例子。</p><hr>',10)),s("p",null,[e[1]||(e[1]=o("via: ",-1)),r(t,{href:"https://www.opensourceforu.com/2022/10/google-ai-unveils-a-new-open-source-library-for-array-storage/"},{default:n(()=>[...e[0]||(e[0]=[o("https://www.opensourceforu.com/2022/10/google-ai-unveils-a-new-open-source-library-for-array-storage/",-1)])]),_:1})]),s("p",null,[e[6]||(e[6]=o("作者：",-1)),r(t,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:n(()=>[...e[2]||(e[2]=[o("Laveesh Kocher",-1)])]),_:1}),e[7]||(e[7]=o(" 選題：",-1)),r(t,{href:"https://github.com/lkxed"},{default:n(()=>[...e[3]||(e[3]=[o("lkxed",-1)])]),_:1}),e[8]||(e[8]=o(" 譯者：",-1)),r(t,{href:"https://github.com/KevinZonda"},{default:n(()=>[...e[4]||(e[4]=[o("KevinZonda",-1)])]),_:1}),e[9]||(e[9]=o(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[5]||(e[5]=[o("wxy",-1)])]),_:1})]),s("p",null,[e[12]||(e[12]=o("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[o("LCTT",-1)])]),_:1}),e[13]||(e[13]=o(" 原創編譯，",-1)),r(t,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[o("Linux中國",-1)])]),_:1}),e[14]||(e[14]=o(" 榮譽推出",-1))])])}const x=a(f,[["render",d]]);export{I as __pageData,x as default};
